import {crmLoginUrl} from './crm-navigation.mjs';
import {renderSessionNotice,SESSION_CSS,SESSION_CLIENT} from './wasion-experience/session.mjs';
import { wasionWorkspaceHref } from './crm-project-previews.mjs';
import { DTECH } from './wasion-experience/content-data.mjs';
import content from './wasion-demo-content.json' with { type: 'json' };
import { renderHeader, renderHome, renderFooter, SHELL_CSS, SHELL_CLIENT } from './wasion-experience/shell.mjs';
import { EXPERIENCE_ROUTES, renderExperiencePage, renderRelatedExperience, renderSolutionExperience, CONTENT_CSS, CONTENT_CLIENT } from './wasion-experience/content.mjs';
import { renderSearch, SEARCH_CSS, SEARCH_CLIENT } from './wasion-experience/search.mjs';
import { buildDemoMetadata, renderLegalPage, LEGAL_ROUTES, DISCOVERY_CSS, DISCOVERY_CLIENT, renderCookiePreferences } from './wasion-experience/discovery.mjs';
import { renderContact, CONTACT_CSS, CONTACT_CLIENT } from './wasion-experience/contact.mjs';
export const WASION_PAGES = content.pages;
import { WASION_STYLES, WASION_DEFAULT_STYLE, wasionStyleBase } from './wasion-demo-styles.mjs';
import { ATMOSPHERIC_CSS } from './wasion-demo-atmospheric.mjs';
import { renderEditorialHome, PLANHAT_CSS, ORDERFUL_CSS, OVERSEAS_CSS, OVERSEAS_CLIENT } from './wasion-demo-editorial.mjs';
import { renderIndustrialHome, INDUSTRIAL_CSS, INDUSTRIAL_CLIENT } from './wasion-demo-industrial.mjs';
import { decorateIndustrialSearch, INDUSTRIAL_SEARCH_CSS } from './wasion-industrial-search.mjs';
import { renderIndustrialProduct, INDUSTRIAL_PRODUCT_CSS } from './wasion-industrial-product.mjs';
const STYLE_CSS = Object.freeze({classic:'',atmospheric:ATMOSPHERIC_CSS,planhat:PLANHAT_CSS,orderful:ORDERFUL_CSS+OVERSEAS_CSS,industrial:INDUSTRIAL_CSS});
export const WASION_DEMO_ROUTES = [...WASION_PAGES.map(p => p.slug), ...EXPERIENCE_ROUTES.map(p => p.slug), ...LEGAL_ROUTES.map(p => p.slug), 'search', 'styles'];
export const isWasionDemoSlug = slug => WASION_DEMO_ROUTES.includes(slug);
export function wasionDemoPage(nonce, { slug = 'home', query = '', style = WASION_DEFAULT_STYLE } = {}) {
if (!Object.hasOwn(WASION_STYLES, style)) return null;
const base = wasionStyleBase(style);
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const title = page => page.title.replace(/ - (Content Page|Content|Relevant Product|Newsroom|IEC Smart Meters|IEC Prepaid Meters|ANSI Meters|Cellular Communication|Wi-SUN RF Mesh)$/, '');
const href = page => page.slug === 'home' ? base : `${base}/${page.slug}`;
const image = page => page?.images?.find(url => url.includes('/uploads/images/')) || page?.images?.find(url => !/icon|x-pro-info|searc/i.test(url));
const summary = page => {
  if (page.pageType === 'detail' && page.category === 'Products') return [page.paragraphs?.[0], page.features?.[0]].filter(Boolean).join(' · ').slice(0, 190);
  return (page.summary || page.paragraphs?.find(p => p.length > 55) || page.features?.[0] || `Explore ${title(page)} from Wasion International.`).slice(0, 210);
};
const find = slug => WASION_PAGES.find(page => page.slug === slug);
const external = (url, label, cls = '') => `<a class="${cls}" href="${escape(encodeURI(url))}" target="_blank" rel="noopener noreferrer">${escape(label)} <span aria-hidden="true">↗</span></a>`;
const img = (url, alt, cls = '', lazy = true) => url ? `<img class="${cls}" src="${escape(encodeURI(url))}" alt="${escape(alt)}" ${lazy ? 'loading="lazy"' : 'fetchpriority="high"'} decoding="async">` : '';
const arrow = '<span aria-hidden="true">↗</span>';
const groupDescriptions = {
  'electricity-meters': 'ANSI, IEC smart and prepaid meters for utility metering and revenue management.',
  telecommunications: 'Connect field devices with cellular, RF mesh and wired communication.',
  'system-software': 'Manage devices, meter data, prepayment and the utility customer lifecycle.',
  'water-gas-meters': 'Smart water and gas metering for measurement, communication and control.',
  'renewable-energy': 'Explore energy storage and renewable energy products from the official portfolio.',
  'intelligent-power-distribution': 'Discover equipment for intelligent power distribution networks.'
};

function card(page, large = false) {
  const description = groupDescriptions[page.slug] || summary(page);
  return `<a class="wd-card ${large ? 'wd-card-large' : ''} ${page.category === 'Products' && page.pageType === 'detail' ? 'wd-product-card' : ''}" href="${href(page)}"><div class="wd-card-image">${img(image(page), title(page))}</div><div class="wd-card-body"><span class="wd-overline">${escape(page.category)}</span><h3>${escape(title(page))}</h3><p>${escape(description)}</p><span class="wd-card-link">Explore ${arrow}</span></div></a>`;
}

function searchForm(query = '', hero = false) {
  return `<form class="wd-search ${hero ? 'wd-search-hero' : ''}" action="${base}/search" method="post" role="search"><span class="wd-search-icon" aria-hidden="true">⌕</span><input type="search" name="q" maxlength="500" required value="${escape(query)}" aria-label="Search Wasion products and solutions" placeholder="Ask about a product, specification or solution…"><button type="submit">Search with AI ${arrow}</button></form>`;
}

function legacyHeader(slug) {
  return `<a class="wd-skip" href="#main">Skip to content</a><div class="wd-utility"><div class="wd-container"><span>Wasion International <span class="wd-separator">/</span> Customer preview</span><div><a class="wd-workspace-return" href="${escape(wasionWorkspaceHref)}">Client workspace</a><a href="${base}/contact">Global contacts</a><details class="wd-language"><summary>English <span aria-hidden="true">⌄</span></summary><div><a href="${base}" lang="en" aria-current="true">English ✓</a>${external('https://www.wasion.com/', '中文官网')}</div></details></div></div></div><header class="wd-header"><div class="wd-container wd-nav"><a class="wd-brand" href="${base}" aria-label="Wasion International home">${img(content.logoUrl, 'Wasion', '', false)}</a><button class="wd-menu" aria-label="Open navigation" aria-expanded="false" aria-controls="wd-navigation">☰</button><nav id="wd-navigation" aria-label="Main navigation">${[['products', 'Products'], ['solutions', 'Solutions'], ['success-stories', 'Success stories'], ['resources', 'Resources'], ['about', 'About Wasion']].map(([key, label]) => `<a href="${base}/${key}" ${slug === key ? 'aria-current="page"' : ''}>${label}</a>`).join('')}<a class="wd-contact-nav" href="${base}/contact">Contact us ${arrow}</a></nav><a class="wd-search-trigger" href="${base}/search" aria-label="Open AI search">⌕ <span>AI search</span></a></div></header>`;
}

function legacyFooter() {
  return `<section class="wd-contact-band"><div class="wd-container"><div><span class="wd-overline">LET’S TALK</span><h2>Build your next utility project with Wasion.</h2><p>Discuss your application, specifications and project requirements.</p></div><a class="wd-button wd-button-light" href="${base}/contact">Talk to our team ${arrow}</a></div></section><footer class="wd-footer"><div class="wd-container"><div class="wd-footer-top"><a class="wd-brand" href="${base}">${img(content.logoUrl, 'Wasion International')}</a><div><h3>Explore Wasion</h3>${['products', 'solutions', 'success-stories', 'resources'].map(s => `<a href="${base}/${s}">${escape(title(find(s)))}</a>`).join('')}</div><div><h3>Company</h3>${['about', 'newsroom', 'careers', 'contact'].map(s => `<a href="${base}/${s}">${escape(title(find(s)))}</a>`).join('')}</div><div><h3>Official information</h3>${external('https://en.wasion.com/', 'Wasion International')}${external('http://website.wasionholdings.wisdomir.com/en/ir_ann.php', 'Investor relations')}<a href="${base}/policy">Privacy & terms</a></div></div><div class="wd-footer-bottom"><span>Wasion website concept · Private customer demo</span><span>Content reproduced from ${external('https://en.wasion.com/', 'en.wasion.com')} · ${escape(content.generatedAt?.slice(0, 10) || '2026-10-14')}</span></div></div></footer>`;
}

function legacyHome() {
  const families = Object.keys(groupDescriptions).map(find).filter(Boolean);
  const stories = WASION_PAGES.filter(p => p.category === 'Success Stories' && p.pageType === 'detail').slice(0, 3);
  const featured = ['ameter300-three-phase-smart-energy-meter', 'ameter100-single-phase-smart-energy-meter', 'i-110-series-smart-water-meter'].map(find).filter(Boolean);
  return `<section class="wd-home-hero"><div class="wd-container wd-hero-grid"><div class="wd-hero-copy"><span class="wd-overline">INTELLIGENT METERING. CONNECTED UTILITIES.</span><h1>A smarter connection.<br>From meter to utility.</h1><p>Explore Wasion’s metering, communication and energy solutions. Find the right information for your next project.</p><div class="wd-actions"><a class="wd-button" href="${base}/products">Explore our portfolio ${arrow}</a><a class="wd-text-link" href="${base}/solutions">Discover solutions →</a></div></div><div class="wd-hero-photo">${img('https://en.wasion.com/public/uploads/images/20220517/b5351d87595d0701db16c017820c88e1.jpg', 'Wasion intelligent power distribution infrastructure', '', false)}<div class="wd-photo-caption"><span>CONNECTED INFRASTRUCTURE</span><span>From measurement to management</span></div></div></div></section><section class="wd-ai-entry wd-container" aria-labelledby="ai-entry-title"><div class="wd-ai-label"><span aria-hidden="true">✦</span> <h2 id="ai-entry-title">Find answers. Move your project forward.</h2><span class="wd-pill">Wasion AI search</span></div>${searchForm('', true)}<div class="wd-prompts"><span>Try asking</span>${['Which three-phase smart meters support AMI?', 'How does Wi-SUN RF Mesh work?', 'What communication options does I-110 support?'].map(q => `<a href="${base}/search?q=${encodeURIComponent(q)}">${escape(q)} ↗</a>`).join('')}</div></section><section class="wd-section wd-container"><div class="wd-section-heading"><div><span class="wd-overline">PRODUCT PORTFOLIO</span><h2>One connected portfolio.<br>Every part of your utility.</h2></div><p>Start with your application. Explore the products and systems that connect your field assets to actionable information.</p></div><div class="wd-grid wd-grid-three">${families.map(p => card(p, true)).join('')}</div></section><section class="wd-feature-section"><div class="wd-container"><div class="wd-section-heading"><div><span class="wd-overline">SMART METERING</span><h2>Meet the meters.</h2></div><a class="wd-text-link" href="${base}/electricity-meters">View electricity meters →</a></div><div class="wd-grid wd-grid-three">${featured.map(p => card(p)).join('')}</div></div></section><section class="wd-section wd-container"><div class="wd-section-heading"><div><span class="wd-overline">SOLUTIONS FOR UTILITIES</span><h2>Connect the entire journey.</h2></div><a class="wd-text-link" href="${base}/solutions">All solutions →</a></div><div class="wd-solution-list">${WASION_PAGES.filter(p => p.category === 'Solutions' && p.pageType === 'detail').slice(0, 4).map(p => `<a href="${href(p)}"><h3>${escape(title(p))}</h3><p>${escape(summary(p))}</p>${arrow}</a>`).join('')}</div></section><section class="wd-feature-section"><div class="wd-container"><div class="wd-section-heading"><div><span class="wd-overline">SUCCESS STORIES</span><h2>See Wasion in the field.</h2></div><a class="wd-text-link" href="${base}/success-stories">Explore project stories →</a></div><div class="wd-grid wd-grid-three">${stories.map(p => card(p, true)).join('')}</div></div></section>`;
}

function collection(page) {
  let children;
  if (page.slug === 'products') children = Object.keys(groupDescriptions).map(find).filter(Boolean);
  else if (Object.hasOwn(groupDescriptions, page.slug)) {
    const prefix = { 'electricity-meters': /\/(IEC-|ANSI)/, telecommunications: /\/(Cellular|Wi-SUN)/, 'system-software': /\/RelevantProduct\//, 'water-gas-meters': /\/proWateRel\//, 'renewable-energy': /\/proNewRel\//, 'intelligent-power-distribution': /\/proPowerRel\// }[page.slug];
    children = WASION_PAGES.filter(p => p.pageType === 'detail' && p.category === 'Products' && prefix.test(p.url));
  } else children = WASION_PAGES.filter(p => p.category === page.category && p.pageType === 'detail');
  const info = groupDescriptions[page.slug] || { solutions: 'From meter-to-cash to field communications, explore Wasion’s integrated solutions for utility operations.', 'success-stories': 'Explore real utility and energy projects documented by Wasion International.', newsroom: 'The latest company and project updates from Wasion International.', resources: 'Read official policies, certifications and product resources.' }[page.slug] || summary(page);
  const resources = page.slug === 'resources' ? resourceContent(page) : '';
  return `${breadcrumb(page)}<section class="wd-page-intro wd-container"><span class="wd-overline">${escape(page.category)}</span><h1>${escape(title(page))}</h1><p>${escape(info)}</p>${external(page.url, 'View official source', 'wd-source-link')}</section><section class="wd-container wd-collection"><div class="wd-collection-toolbar"><span>${children.length ? `${children.length} ${page.slug === 'products' ? 'product families' : 'pages to explore'}` : 'Official Wasion information'}</span><a href="${base}/search">Need help finding something? Search with AI →</a></div>${children.length ? `<div class="wd-grid wd-grid-three">${children.map(p => card(p, true)).join('')}</div>` : resources || `<div class="wd-reading">${page.paragraphs.map(p => `<p>${escape(p)}</p>`).join('')}<p>More products are available in the official portfolio.</p>${external(page.url, 'Explore the complete official category', 'wd-button')}</div>`}</section>`;
}

function breadcrumb(page) {
  return `<div class="wd-container wd-breadcrumb"><a href="${base}">Home</a><span aria-hidden="true">/</span>${page.pageType === 'detail' ? `<a href="${base}/${page.category === 'Products' ? 'products' : page.category === 'Solutions' ? 'solutions' : page.category === 'Success Stories' ? 'success-stories' : page.category === 'Company' ? 'about' : 'newsroom'}">${escape(page.category)}</a><span aria-hidden="true">/</span>` : ''}<span>${escape(title(page))}</span></div>`;
}

function resourceContent(page) {
  return `<div class="wd-reading"><h2>Documents & certifications</h2><p>Browse documents published by Wasion International. Availability and current validity are determined by the official source.</p>${page.downloads?.length ? `<div class="wd-downloads">${page.downloads.map(d => external(d.url, d.title || 'Open document')).join('')}</div>` : '<p>Open the official resource center for available documents and downloads.</p>'}${external(page.url, 'Open the official resource center', 'wd-text-link')}</div>`;
}

function contact(page) {
  const email = (page.paragraphs || []).flatMap(p => p.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig) || [])[0];
  return `${breadcrumb(page)}<section class="wd-page-intro wd-container"><span class="wd-overline">CONTACT WASION</span><h1>Let’s talk about your project.</h1><p>Connect with the Wasion team for product information, technical specifications and utility project requirements.</p></section><section class="wd-container wd-contact-layout"><div class="wd-reading"><h2>Tell us what you’re building.</h2><p>Include your application, required standards, communication environment, country and estimated deployment size so the team can direct your enquiry.</p>${email ? `<a class="wd-button" href="mailto:${escape(email)}">Email Wasion ${arrow}</a>` : external(page.url, 'Contact the Wasion team', 'wd-button')}${external(page.url, 'View official contact page', 'wd-source-link')}<h3>Official contact details</h3>${page.paragraphs?.length ? page.paragraphs.map(p => `<p>${escape(p)}</p>`).join('') : '<p>Use the official contact page for current regional contacts and office details.</p>'}</div><aside class="wd-contact-card"><h3>Before you enquire</h3><ul><li>Product or solution of interest</li><li>Technical requirements and standards</li><li>Communication and system integration</li><li>Project country and delivery timeline</li></ul><a href="${base}/search">Find product information first →</a></aside></section>`;
}

function detail(page) {
  const product = page.category === 'Products';
  const candidates = WASION_PAGES.filter(p => p.slug !== page.slug && p.category === page.category && p.pageType === 'detail');
  const family = new URL(page.url).pathname.split('/')[1];
  const sameFamily = candidates.filter(p => new URL(p.url).pathname.split('/')[1] === family);
  const related = (sameFamily.length ? sameFamily : candidates).slice(0, 3);
  const tableText = new Set((page.tables || []).flat(2));
  const paragraphs = [...new Set(page.paragraphs || [])].filter(p => !tableText.has(p) && !(page.features || []).includes(p));
  return `${breadcrumb(page)}<section class="wd-detail-hero wd-container"><div><span class="wd-overline">${escape(page.category)}</span><h1>${escape(title(page))}</h1><p>${escape(summary(page))}</p><div class="wd-actions"><a class="wd-button" href="${base}/contact">${product ? 'Discuss this product' : 'Discuss your project'} ${arrow}</a><a class="wd-text-link" href="${base}/search?q=${encodeURIComponent(`Tell me about ${title(page)}`)}">Ask Wasion AI →</a></div>${external(page.url, 'View official source', 'wd-source-link')}</div><div class="wd-detail-image ${product ? 'wd-product-image' : ''}">${img(image(page), title(page), '', false)}</div></section><nav class="wd-section-nav wd-container" aria-label="Page sections"><a href="#overview">Overview</a>${page.features?.length ? '<a href="#features">Key features</a>' : ''}${page.tables?.length ? '<a href="#specifications">Technical information</a>' : ''}<a href="#documents">Documents & sources</a></nav><section class="wd-container wd-detail-layout"><article class="wd-reading"><section id="overview"><span class="wd-overline">OVERVIEW</span><h2>${product ? 'Product information' : 'About this ' + (page.category === 'Solutions' ? 'solution' : page.category === 'Newsroom' ? 'update' : 'project')}</h2>${paragraphs.map(p => `<p>${escape(p)}</p>`).join('')}</section>${page.features?.length ? `<section id="features"><h2>Key features</h2><ul class="wd-feature-list">${page.features.map(f => `<li>${escape(f)}</li>`).join('')}</ul></section>` : ''}${page.tables?.length ? `<section id="specifications"><h2>Technical information</h2>${['orderful','industrial'].includes(style) ? '<p class="wd-table-hint">Swipe the table to see all columns, or focus it and use the arrow keys.</p>' : ''}<div class="wd-tables"${['orderful','industrial'].includes(style) ? ' tabindex="0" role="region" aria-label="Scrollable official technical information"' : ''}>${page.tables.map(rows => `<table><caption>${escape(title(page))} — official technical information</caption><tbody>${rows.map(row => row.length === 1 ? `<tr><td colspan="${Math.max(...rows.map(r => r.length))}">${escape(row[0])}</td></tr>` : `<tr>${row.map((cell, i) => `<${i === 0 && row.length > 1 ? 'th scope="row"' : 'td'}>${escape(cell)}</${i === 0 && row.length > 1 ? 'th' : 'td'}>`).join('')}</tr>`).join('')}</tbody></table>`).join('')}</div></section>` : ''}<section id="documents"><h2>Documents & sources</h2><div class="wd-source-box"><span class="wd-overline">OFFICIAL SOURCE</span>${external(page.url, title(page))}<p>Content reproduced from Wasion International, ${escape(content.generatedAt?.slice(0, 10) || '2026-10-14')}. Confirm specifications, availability and project suitability with Wasion.</p></div>${page.downloads?.length ? `<div class="wd-downloads">${page.downloads.map(d => external(d.url, d.title || 'Open document')).join('')}</div>` : `<p class="wd-muted">${escape(page.downloadNotice || 'No downloadable document was provided on this source page. Contact Wasion for current documentation.')}</p>`}</section></article><aside class="wd-detail-aside"><span class="wd-overline">NEXT STEP</span><h3>From information<br>to your application.</h3><p>Confirm the specification, communication options and integration requirements for your project.</p><a class="wd-button" href="${base}/contact">Contact us ${arrow}</a><div class="wd-aside-rule"></div><h3>Explore more</h3>${related.map(p => `<a class="wd-related-link" href="${href(p)}">${escape(title(p))} →</a>`).join('')}</aside></section>`;
}

function company(page) {
  return `${breadcrumb(page)}<section class="wd-page-intro wd-container"><span class="wd-overline">${escape(page.category)}</span><h1>${escape(title(page))}</h1><p>${page.slug === 'about' ? 'Intelligent metering, connected systems and energy solutions for utilities around the world.' : escape(summary(page))}</p></section><section class="wd-container wd-company-layout"><article class="wd-reading">${page.paragraphs.map(p => `<p>${escape(p)}</p>`).join('')}${page.features?.length ? `<ul class="wd-feature-list">${page.features.map(f => `<li>${escape(f)}</li>`).join('')}</ul>` : ''}<div class="wd-source-box">${external(page.url, 'Read the official Wasion page')}</div></article>${image(page) ? `<aside>${img(image(page), title(page), 'wd-company-image')}</aside>` : ''}</section>`;
}

function legacySearch(query) {
  return `<div class="wd-search-banner"><div class="wd-container">${searchForm(query)}<p>Search Wasion’s official products, solutions and public documents.</p></div></div><div class="wd-container wd-breadcrumb"><a href="${base}">Home</a><span>/</span><span>AI search</span></div><section class="wd-container wd-search-results"><span class="wd-overline">WASION INTELLIGENT SEARCH</span><h1 id="wd-query-title">${query ? `Results for “${escape(query)}”` : 'What would you like to know?'}</h1><p class="wd-muted" id="wd-result-count">${query ? 'Finding relevant official information…' : 'Start with a question or browse the official page collection below.'}</p><div class="wd-tabs" role="tablist" aria-label="Result categories">${[['all', 'All'], ['Products', 'Products'], ['Solutions', 'Solutions'], ['Resources', 'Resources']].map(([key, label], i) => `<button type="button" role="tab" aria-controls="wd-results" id="wd-tab-${key}" aria-selected="${!i}" tabindex="${i ? -1 : 0}" data-filter="${key}">${label}<span></span></button>`).join('')}</div><div class="wd-search-layout"><div><section class="wd-ai-summary" id="wd-ai-summary" aria-labelledby="wd-ai-title" aria-live="polite"><div class="wd-ai-summary-heading"><h2 id="wd-ai-title"><span aria-hidden="true">✦</span> ${query ? 'Preparing your AI summary' : 'Search with confidence'}</h2><span id="wd-ai-status" class="wd-pill">Official Wasion sources</span></div><div id="wd-answer"><p>${query ? 'Looking up the relevant pages and preparing a source-based answer.' : 'Ask in your own words. See a concise answer, then explore the products and original source pages behind it.'}</p></div><div class="wd-citations" id="wd-citations"></div><p class="wd-ai-note">AI summaries may contain errors. Refer to the linked official pages and confirm specifications with Wasion.</p></section><section id="wd-results" role="tabpanel" aria-labelledby="wd-tab-all"><h2 id="wd-matches-heading">${query ? 'Matching pages' : 'Explore the official page collection'}</h2><div id="wd-result-list" class="wd-result-list"></div><button id="wd-show-more" class="wd-show-more" type="button" hidden>Show more pages ↓</button></section></div><aside class="wd-search-aside"><span class="wd-overline">QUICK LINKS</span><h3>Start with your application.</h3>${['electricity-meters', 'water-gas-meters', 'solutions', 'system-software', 'resources'].map(s => `<a href="${base}/${s}">${escape(title(find(s)))} →</a>`).join('')}<div class="wd-aside-rule"></div><h3>Need technical guidance?</h3><p>Discuss your project requirements with the Wasion team.</p><a class="wd-button" href="${base}/contact">Contact an expert ${arrow}</a></aside></div></section>`;
}

function styleSwitch() {
 const target = slug === 'styles' ? 'home' : slug;
 return `<nav class="wd-style-switch" aria-label="Preview styles"><a href="/demo/wasion/styles" aria-label="Design previews">${['industrial','orderful'].includes(style) ? 'Styles' : 'Design previews'}</a>${Object.entries(WASION_STYLES).map(([key,value]) => `<a data-style-base="${wasionStyleBase(key)}" href="${wasionStyleBase(key)}${target === 'home' ? '' : '/' + target}${target === 'search' && query ? '?' + new URLSearchParams({q:query}) : ''}" ${style === key ? 'aria-current="true"' : ''}>${value.label}</a>`).join('')}</nav>`;
}
function styleGallery() {
 return `<section class="wd-style-gallery wd-container"><span class="wd-overline">WASION WEBSITE PREVIEWS</span><h1>One portfolio.<br>Different perspectives.</h1><p>Choose a design direction to explore the same Wasion products, solutions and source-based search.</p>${Object.entries(WASION_STYLES).map(([key,value]) => `<a class="wd-style-choice${key === WASION_DEFAULT_STYLE ? ' wd-style-recommended' : ''}" href="${wasionStyleBase(key)}">${key === WASION_DEFAULT_STYLE ? '<span class="wd-recommendation">Default · Brand &amp; product experience</span>' : ''}<h2>${value.label} ↗</h2><p>${value.description}</p></a>`).join('')}</section>`;
}


const helpers = { escape, title, href, image, summary, external, img, card };
const context = { pages: WASION_PAGES, helpers, base };
function renderPage() {
  const page = find(slug) || EXPERIENCE_ROUTES.find(p => p.slug === slug) || LEGAL_ROUTES.find(p => p.slug === slug);
  if (!page && !['search', 'styles'].includes(slug)) return null;
  const heading = slug === 'styles' ? 'Design previews' : slug === 'search' ? 'AI search' : slug === 'home' ? 'Electricity metering & connected utilities' : title(page);
  let body = slug === 'styles' ? styleGallery() : slug === 'home' ? (style === 'industrial' ? renderIndustrialHome(context) : renderEditorialHome(style,context) || renderHome(context)) : slug === 'search' ? renderSearch(query,base) : slug === 'contact' ? renderContact(context) : renderLegalPage(slug,base) || renderExperiencePage(slug,context);
  if (slug === 'search' && style === 'industrial') body = decorateIndustrialSearch(body,context);
  const industrialProduct = style === 'industrial' && page?.category === 'Products' && page?.pageType === 'detail';
  if (industrialProduct) body = renderIndustrialProduct(page,{...context,generatedAt:content.generatedAt});
  if (!body && page.category === 'Solutions' && page.pageType === 'detail') body = renderSolutionExperience(page,context);
  if (!body) body = slug === 'policy' ? company(page) : page.pageType === 'detail' ? detail(page) : ['products','solutions','success-stories','newsroom','resources',...Object.keys(groupDescriptions)].includes(slug) ? collection(page) : company(page);
  if (page?.category === 'Products' && page?.pageType === 'detail') body += renderRelatedExperience(page,context);
  const data = [...WASION_PAGES,{...DTECH,features:[],tables:[]}].map(p => ({ id:p.slug,title:title(p),category:p.category,href:href(p),url:p.url,excerpt:summary(p),summary:summary(p),image:image(p),text:[p.title,...p.paragraphs,...p.features,JSON.stringify(p.tables)].join(' ').slice(0,18000) }));
  const description = slug === 'home' ? 'Explore Wasion electricity metering, AMI and connected utility products, solutions and project experience.' : page?.description || page?.summary || (page ? summary(page) : 'Search official Wasion products and solutions with cited AI answers.');
  const metadata = buildDemoMetadata({slug,title:heading,description,page,nonce,base});
  const client = slug === 'search' ? SEARCH_CLIENT : CLIENT;
  const styleClient = style === 'industrial' ? INDUSTRIAL_CLIENT : '';
  const searchStyle = slug === 'search' && style === 'industrial' ? INDUSTRIAL_SEARCH_CSS : '';
  const productStyle = industrialProduct ? INDUSTRIAL_PRODUCT_CSS : '';
  const pageUrl=slug==='home'?base:base+'/'+slug;const loginUrl=crmLoginUrl(pageUrl);
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">${metadata}<style nonce="${escape(nonce)}">${CSS}${SHELL_CSS}${CONTENT_CSS}${SEARCH_CSS}${DISCOVERY_CSS}${CONTACT_CSS}${SESSION_CSS}${STYLE_CSS[style]}${searchStyle}${productStyle}${STYLE_SWITCH_CSS}</style></head><body${style !== 'classic' ? ` class="wd-style-${style} ${slug === 'home' ? 'wd-is-home' : ''}"` : ''}>${renderSessionNotice({loginUrl})}<div id="wd-protected">${styleSwitch()}${renderHeader(slug,context)}${!['industrial','orderful'].includes(style) && !['home','search','styles'].includes(slug) ? `<div class="wd-mini-search wd-container">${searchForm()}</div>` : ''}<main id="main">${body}</main>${renderFooter(context)}${renderCookiePreferences(base,{showTrigger:false})}</div><script nonce="${escape(nonce)}">const WASION_BASE=${JSON.stringify(base)};const CRM_LOGIN_URL=${JSON.stringify(loginUrl).replace(/</g,'\\u003c')};const CRM_PAGE_URL=${JSON.stringify(pageUrl).replace(/</g,'\\u003c')};const WASION_DATA=${JSON.stringify(data).replace(/</g,'\\u003c')};const SEARCH_QUERY=${JSON.stringify(query).replace(/</g,'\\u003c')};(()=>{${client}})();${SESSION_CLIENT}${SHELL_CLIENT}${CONTENT_CLIENT}${DISCOVERY_CLIENT}${CONTACT_CLIENT}${STYLE_SWITCH_CLIENT}${OVERSEAS_CLIENT}${styleClient}</script></body></html>`;
}

return renderPage();
}

